@doc """
    updateCurrentState(mp, t::Real, strain::Istensor)
    updateCurrentState(mp, t::Real, F::Itensor)

Set the trial state of the material point at time `t`.

# Details
Small strain points take the linearised strain as an [`Istensor`](@ref); finite strain points
take the deformation gradient as a general [`Itensor`](@ref).

This sets the *current* state only. A solver iterating on a step calls this repeatedly, then
either accepts the step with
[`commitCurrentState`](@ref MuesliMaterials.commitCurrentState) or discards it with
[`resetCurrentState`](@ref MuesliMaterials.resetCurrentState).

There is no bang, because the call advances the point's own history rather than filling an
argument.
"""
function updateCurrentState end

@doc """
    commitCurrentState(mp)

Accept the current state as converged.

# See Also
- [`resetCurrentState`](@ref MuesliMaterials.resetCurrentState)
"""
function commitCurrentState end

@doc """
    resetCurrentState(mp)

Discard the current state and return to the last converged one.
"""
function resetCurrentState end

@doc """
    setConvergedState(mp, t::Real, strain)

Set the converged state directly, bypassing the trial state.

Useful when restoring a material point from stored history. Plastic, viscoelastic and
viscoplastic points take additional internal variables; see their MUESLI documentation.
"""
function setConvergedState end

@doc """
    stress!(mp, σ::Istensor)

Compute the Cauchy stress of a small strain material point into `σ`.

# Examples
```julia
σ = Istensor()
stress!(mp, σ)
```
"""
function stress! end

@doc """
    deviatoricStress!(mp, s::Istensor)

Compute the deviatoric part of the stress into `s`.
"""
function deviatoricStress! end

@doc """
    pressure(mp)

The pressure, i.e. minus one third of the trace of the stress.
"""
function pressure end

@doc """
    tangentTensor!(mp, ℂ::Itensor4)

Compute the small strain tangent ``\\partial\\sigma/\\partial\\varepsilon`` into `ℂ`.

For a linear isotropic material this is
``\\mathbb{C}_{ijkl} = \\lambda\\delta_{ij}\\delta_{kl} +
\\mu(\\delta_{ik}\\delta_{jl} + \\delta_{il}\\delta_{jk})``, and contracting it with the strain
reproduces the stress.
"""
function tangentTensor! end

@doc """
    tangentMatrix!(mp, C::Matrix{Float64})

Compute the small strain tangent as a ``6 \\times 6`` matrix into the preallocated `C`.

The rows and columns follow MUESLI's Voigt order ``[11, 22, 33, 23, 13, 12]``. The entries are
the tensor components ``\\mathbb{C}_{abcd}`` of the corresponding index pairs, so the matrix
acts on a strain vector with *engineering* shear components ``[\\varepsilon_{11},
\\varepsilon_{22}, \\varepsilon_{33}, 2\\varepsilon_{23}, 2\\varepsilon_{13},
2\\varepsilon_{12}]``. For an isotropic material the diagonal shear entries are ``\\mu``.

Any shape other than ``6 \\times 6`` raises an error.

# See Also
- [`tangentTensor!`](@ref MuesliMaterials.tangentTensor!) for the fourth-order form
"""
function tangentMatrix! end

@doc """
    thermodynamicPotentials(mp) -> ThPotentials

The thermodynamic potentials of the current state of a small strain material point.

Read them with the accessors `chemical`, `deviatoric`, `dissipated`, `entropy`, `freeEnergy`,
`freeEntropy`, `internalEnergy`, `kineticPotential`, `minimizing` and `volumetric`. Which of
them a material fills in is up to the material; the others are zero. A linear isotropic
material, for instance, sets `volumetric`, `deviatoric` and `internalEnergy`.
"""
function thermodynamicPotentials end

@doc """
    contractWithAllTangents!(mp, v1::Ivector, v2::Ivector, Tdev::Itensor, Tmixed::Istensor) -> Float64

Contract the deviatoric and mixed tangents of a finite strain material point in one call.

Fills `Tdev` and `Tmixed`, exactly as `contractWithDeviatoricTangent!` and
`contractWithMixedTangent!` would separately, and returns the volumetric stiffness.
"""
function contractWithAllTangents! end

@doc """
    firstPiolaKirchhoffStress!(mp, P::Itensor)

Compute the first Piola-Kirchhoff stress ``P`` into `P`.

``P`` is **not** symmetric, hence the general [`Itensor`](@ref). It relates to the second
Piola-Kirchhoff stress by ``P = FS``.
"""
function firstPiolaKirchhoffStress! end

@doc """
    secondPiolaKirchhoffStress!(mp, S::Istensor)

Compute the symmetric second Piola-Kirchhoff stress ``S`` into `S`.

``S`` is unaffected by a rigid rotation of the deformation, which makes it the convenient
measure for a material-frame formulation.
"""
function secondPiolaKirchhoffStress! end

@doc """
    KirchhoffStress!(mp, τ::Istensor)

Compute the Kirchhoff stress ``\\tau = J\\sigma = PF^{T}`` into `τ`.
"""
